syntax:
union union_name {
    data_type1 member1;
    data_type2 member2;
    ...
    data_typeN memberN;
};

code_example:
#include <stdio.h>

union Data {
    int ival;
    float fval;
    char sval[10];
};

int main() {
    union Data u;

    u.ival = 10;
    printf("Integer value: %d\n", u.ival);

    u.fval = 3.14f;
    printf("Float value: %f\n", u.fval);

    strcpy(u.sval, "Hello");
    printf("String value: %s\n", u.sval);

    return 0;
}
